document.querySelectorAll(".markdown-body pre:not(.mermaid)").forEach(function(e){var t=document.createElement("button");t.className="copy-btn",t.type="button",t.textContent="Copy",t.onclick=function(){navigator.clipboard.writeText(e.innerText).then(function(){t.textContent="Copied",setTimeout(function(){t.textContent="Copy"},1500)})},e.style.position="relative",e.appendChild(t)})